{
  "queries": [
    {
      "query": "What was Riona Thorne's initial physiological state or the nature of her life support system before she became a biological conduit for the Entity’s resonance?",
      "chapters": [
        12,
        13,
        15
      ]
    },
    {
      "query": "What are Jora Ward's established tactical protocols or known operational limits regarding containment against dimensional shear and corrosive flux entities?",
      "chapters": [
        2,
        13,
        14
      ]
    },
    {
      "query": "How did XO Cross (Helena) previously categorize threats that were informational or biological in nature, as opposed to purely structural or mechanical failures?",
      "chapters": [
        6,
        10,
        12
      ]
    }
  ]
}
```

